package com.tradingsimulator.ui;
import com.fasterxml.jackson.databind.ObjectMapper; import java.awt.Color; import java.io.InputStream; import java.util.Map;
public record ThemeManager(Color background, Color foreground, Color accent) { public static ThemeManager load(String resource){try(InputStream in=ThemeManager.class.getClassLoader().getResourceAsStream(resource)){if(in==null)return defaults(); Map<?,?> m=new ObjectMapper().readValue(in,Map.class);return new ThemeManager(color(m,"background",Color.DARK_GRAY),color(m,"foreground",Color.WHITE),color(m,"accent",new Color(45,140,220)));}catch(Exception e){return defaults();}} private static Color color(Map<?,?> m,String k,Color d){Object v=m.get(k);if(v instanceof String s){try{return Color.decode(s);}catch(Exception ignored){}}return d;} private static ThemeManager defaults(){return new ThemeManager(Color.DARK_GRAY,Color.WHITE,new Color(45,140,220));} }
